  [[nodiscard]] static constexpr Status DeadlineExceeded() { return PW_STATUS_DEADLINE_EXCEEDED; }
  [[nodiscard]] static constexpr Status NotFound() { return PW_STATUS_NOT_FOUND; }
  [[nodiscard]] static constexpr Status AlreadyExists() { return PW_STATUS_ALREADY_EXISTS; }
  [[nodiscard]] static constexpr Status PermissionDenied() { return PW_STATUS_PERMISSION_DENIED; }
  [[nodiscard]] static constexpr Status ResourceExhausted() { return PW_STATUS_RESOURCE_EXHAUSTED; }
  [[nodiscard]] static constexpr Status FailedPrecondition() { return PW_STATUS_FAILED_PRECONDITION; }
  [[nodiscard]] static constexpr Status Aborted() { return PW_STATUS_ABORTED; }
  [[nodiscard]] static constexpr Status OutOfRange() { return PW_STATUS_OUT_OF_RANGE; }
  [[nodiscard]] static constexpr Status Unimplemented() { return PW_STATUS_UNIMPLEMENTED; }
  [[nodiscard]] static constexpr Status Internal() { return PW_STATUS_INTERNAL; }
  [[nodiscard]] static constexpr Status Unavailable() { return PW_STATUS_UNAVAILABLE; }
  [[nodiscard]] static constexpr Status DataLoss() { return PW_STATUS_DATA_LOSS; }
  [[nodiscard]] static constexpr Status Unauthenticated() { return PW_STATUS_UNAUTHENTICATED; }
  constexpr Status(Code code = PW_STATUS_OK) : code_(code) {}
  constexpr Status(const Status&) = default;
  constexpr Status& operator=(const Status&) = default;
  constexpr Code code() const { return code_; }
  [[nodiscard]] constexpr bool ok() const { return code_ == PW_STATUS_OK; }
  [[nodiscard]] constexpr bool IsCancelled() const { return code_ == PW_STATUS_CANCELLED; }
  [[nodiscard]] constexpr bool IsUnknown() const { return code_ == PW_STATUS_UNKNOWN; }
  [[nodiscard]] constexpr bool IsInvalidArgument() const { return code_ == PW_STATUS_INVALID_ARGUMENT; }
  [[nodiscard]] constexpr bool IsDeadlineExceeded() const { return code_ == PW_STATUS_DEADLINE_EXCEEDED; }
  [[nodiscard]] constexpr bool IsNotFound() const { return code_ == PW_STATUS_NOT_FOUND; }
  [[nodiscard]] constexpr bool IsAlreadyExists() const { return code_ == PW_STATUS_ALREADY_EXISTS; }
  [[nodiscard]] constexpr bool IsPermissionDenied() const { return code_ == PW_STATUS_PERMISSION_DENIED; }
  [[nodiscard]] constexpr bool IsResourceExhausted() const { return code_ == PW_STATUS_RESOURCE_EXHAUSTED; }
  [[nodiscard]] constexpr bool IsFailedPrecondition() const { return code_ == PW_STATUS_FAILED_PRECONDITION; }
  [[nodiscard]] constexpr bool IsAborted() const { return code_ == PW_STATUS_ABORTED; }
  [[nodiscard]] constexpr bool IsOutOfRange() const { return code_ == PW_STATUS_OUT_OF_RANGE; }
  [[nodiscard]] constexpr bool IsUnimplemented() const { return code_ == PW_STATUS_UNIMPLEMENTED; }
  [[nodiscard]] constexpr bool IsInternal() const { return code_ == PW_STATUS_INTERNAL; }
  [[nodiscard]] constexpr bool IsUnavailable() const { return code_ == PW_STATUS_UNAVAILABLE; }
  [[nodiscard]] constexpr bool IsDataLoss() const { return code_ == PW_STATUS_DATA_LOSS; }
  [[nodiscard]] constexpr bool IsUnauthenticated() const { return code_ == PW_STATUS_UNAUTHENTICATED; }
  constexpr void Update(Status other) { if (ok()) { code_ = other.code(); } }
  constexpr void IgnoreError() const {}
  [[nodiscard]] const char* str() const { return pw_StatusString(code_); }
 private:
  Code code_;
};

